    p('Operation: '.$how[0], 'نحوه عملکرد: '.$how[1]); p('Verification: '.$verify[0], 'اعتبارسنجی: '.$verify[1]); p('Production: '.$prod[0], 'نکات Production: '.$prod[1]);
}
